import { readFile } from 'node:fs/promises';
import { z } from 'zod';
import { CheckoutBreakdown, Offer, PriceHistoryRow, StoreProfile } from '@core/offers';

// The committed synthetic dataset (generated by scripts/gen-data.ts), parsed at the boundary.

export type Fixtures = {
  stores: StoreProfile[];
  offers: Offer[];
  priceHistory: PriceHistoryRow[];
  checkouts: CheckoutBreakdown[];
};

const FIXTURES_DIR = new URL('../../data/fixtures/', import.meta.url);

async function readJson<T>(name: string, schema: z.ZodType<T>): Promise<T> {
  const text = await readFile(new URL(name, FIXTURES_DIR), 'utf8');
  return schema.parse(JSON.parse(text));
}

export async function loadFixtures(): Promise<Fixtures> {
  const [stores, offers, priceHistory, checkouts] = await Promise.all([
    readJson('stores.json', z.array(StoreProfile)),
    readJson('offers.json', z.array(Offer)),
    readJson('price-history.json', z.array(PriceHistoryRow)),
    readJson('checkouts.json', z.array(CheckoutBreakdown)),
  ]);
  return { stores, offers, priceHistory, checkouts };
}
